class Solution:
    def canAliceWin(self, nums: list[int]) -> bool:
        single_sum = sum(x for x in nums if x < 10)
        double_sum = sum(x for x in nums if x >= 10)
        return single_sum != double_sum

class Solution {
public:
    bool canAliceWin(vector<int>& nums) {
        int single_sum = 0;
        int double_sum = 0;
        for (int x : nums) {
            if (x < 10) {
                single_sum += x;
            } else {
                double_sum += x;
            }
        }
        return single_sum != double_sum;
    }
};

